            ? ServiceResult<TOut>.Success(mapper(Value))
            : ServiceResult<TOut>.Failure(Error);

    public ServiceResult<TOut> Bind<TOut>(Func<T, ServiceResult<TOut>> binder)
        => IsSuccess
            ? binder(Value)
            : ServiceResult<TOut>.Failure(Error);

