    public async Task<IActionResult> InitiatePayment(
        [FromBody] InitiatePaymentRequest request,
        CancellationToken ct)
    {
        var result = await Mediator.Send(new InitiatePaymentCommand(request.OrderId, request.Gateway), ct);
