             }
             catch (InvalidWalletTransferException ex)
             {
                 transferRepository.Update(transfer);
                 await unitOfWork.SaveChangesAsync(ct);
                 return ServiceResult<ConfirmWalletTransferResultDto>.Failure(ex.Message);
             }

